// Package transport provides predefined transport protocol.
package transport

import (
	"sort"
	"strings"
)

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota
	Framed            // Default protocol
	HTTP
	GRPC
	HESSIAN2

	TTHeaderFramed = TTHeader | Framed

	// Dedicated streaming protocol constants (explicit values, not bitwise composition)
	TTHeaderStreaming Protocol = 64  // TTHeader streaming mode
	GRPCStreaming     Protocol = 128 // gRPC streaming mode
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// protocolNames maps protocol flag bits to their names
var protocolNames = map[Protocol]string{
	PurePayload:       "PurePayload",
	TTHeader:          "TTHeader",
	Framed:            "Framed",
	HTTP:              "HTTP",
	GRPC:              "GRPC",
	HESSIAN2:          "Hessian2",
	TTHeaderStreaming: "TTHeaderStreaming",
	GRPCStreaming:     "GRPCStreaming",
}

// allProtocolFlags lists all single-bit protocol flags in ascending bit order
var allProtocolFlags = []Protocol{
	TTHeader,   // bit 0 (1)
	Framed,     // bit 1 (2)
	HTTP,       // bit 2 (4)
	GRPC,       // bit 3 (8)
	HESSIAN2,   // bit 4 (16)
}

// String prints human readable information.
// For composite protocols (multiple bits set), returns pipe-separated flag names
// sorted by bit value ascending (e.g., "TTHeader|Framed", "Framed|GRPC").
func (tp Protocol) String() string {
	// Handle special cases first
	if tp == PurePayload {
		return "PurePayload"
	}

	// Check for dedicated streaming protocols (non-bitwise)
	if name, ok := protocolNames[tp]; ok && (tp == TTHeaderStreaming || tp == GRPCStreaming) {
		return name
	}

	// Handle bitwise composite protocols
	var flags []string
	var flagValues []int

	for _, flag := range allProtocolFlags {
		if tp&flag != 0 {
			flags = append(flags, protocolNames[flag])
			flagValues = append(flagValues, int(flag))
		}
	}

	if len(flags) == 0 {
		return Unknown
	}

	// Sort flags by bit value (already in order from allProtocolFlags, but ensure consistency)
	// Since allProtocolFlags is already sorted, flags are naturally in order
	// But for clarity and future-proofing, we explicitly maintain the invariant

	return strings.Join(flags, "|")
}
